import{_ as t,o as n,c as r,a3 as i}from"./chunks/framework.B9qR_F1m.js";const b=JSON.parse('{"title":"Die Karte","description":"","frontmatter":{},"headers":[],"relativePath":"start/karte.md","filePath":"start/karte.md"}'),a={name:"start/karte.md"};function d(s,e,o,l,u,h){return n(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="die-karte" tabindex="-1">Die Karte <a class="header-anchor" href="#die-karte" aria-label="Permalink to &quot;Die Karte&quot;">​</a></h1><p>Die Karte ist das Herz von Shardwing. Sie zeigt die DCS-Karte über einer normalen Weltkarte, darauf Routen, Bedrohungen, Grafiken und alles, was zum gerade offenen Bereich gehört.</p><h2 id="bedienen" tabindex="-1">Bedienen <a class="header-anchor" href="#bedienen" aria-label="Permalink to &quot;Bedienen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Was</th><th>Wie</th></tr></thead><tbody><tr><td>Verschieben</td><td>Ziehen</td></tr><tr><td>Zoomen</td><td>Mausrad, Trackpad oder <strong>+ / −</strong> rechts oben</td></tr><tr><td>Ansicht zurücksetzen</td><td>Fadenkreuz-Knopf rechts oben</td></tr><tr><td>Menü „Hier …“</td><td><strong>Rechtsklick</strong> auf die freie Karte – siehe <a href="#rechtsklick-hier">unten</a>. Unten links steht die Position unter dem Mauszeiger im gewählten Format und als Bullseye-Peilung</td></tr><tr><td>Messen</td><td>Lineal-Knopf oder Taste <kbd>M</kbd>, dann Punkte klicken. Shardwing zeigt Kurs und Distanz je Leg und die Summe. <kbd>Esc</kbd> beendet.</td></tr><tr><td>Bullseye-Peilung</td><td><strong>BE</strong> zieht eine Linie vom Bullseye zum Mauszeiger, mit Peilung und Distanz.</td></tr><tr><td>Bullseye versetzen</td><td>Nur Mission Designer: <strong>BE ⌖</strong>, dann auf die Karte klicken – oder im Bullseye-Popup eine Koordinate eingeben.</td></tr></tbody></table><h2 id="kartenebenen" tabindex="-1">Kartenebenen <a class="header-anchor" href="#kartenebenen" aria-label="Permalink to &quot;Kartenebenen&quot;">​</a></h2><p>Links oben über <strong>DCS-Karte</strong> öffnest du die Ebenen:</p><ul><li><strong>Grundkarte:</strong> eine helle bzw. im Dunkelmodus dunkle Straßenkarte (OpenStreetMap). Sie bleibt außerhalb der DCS-Karte immer sichtbar.</li><li><strong>Grundkarte wählen:</strong> <em>Shardwing</em> ist unsere eigene Karte im Stil der DCS-Kartenansicht: helles Land, blaues Wasser, Orte als Flächen, Hauptstraßen rotbraun, Namen nur in lateinischer Schrift, kaum Kleinkram. Sie kommt von unserem eigenen Server. Gibt es sie für eine DCS-Karte (noch) nicht, zeigt Shardwing <em>OpenFreeMap</em>.</li><li><strong>Karte:</strong> darüber wahlweise nichts, die <strong>Geländekarte</strong> oder die <strong>DCS-Karte</strong> (F10-Kartenansicht von DCS Olympus, nicht für jede Karte). Die Deckkraft stellst du darunter ein.</li><li><strong>Geländekarte:</strong> zeichnet Shardwing selbst, im Stil einer Fliegerkarte: Höhenschichten in Farbstufen (Grenzen bei 1000, 2000, 3000, 5000, 7000, 9000, 12000 und 15000 ft), Relief und ab näherem Zoom Höhenlinien mit Höhen in Fuß. Es gibt sie für jede DCS-Karte, auch für Sinai, Kola, Afghanistan, Iraq und Falklands, und sie erscheint ebenso auf den Kartenseiten der Kneeboards. Die Höhen stammen aus echten Geländedaten, nicht aus DCS – kleine Abweichungen zum DCS-Gelände sind möglich.</li><li><strong>Anzeige:</strong> Routen der anderen Flights, Wegpunkte auf diesen Routen, Flugplätze, Bodenstationen (VOR, TACAN, NDB).</li><li><strong>Eigene Kräfte:</strong> Flugzeuge, Hubschrauber, Schiffe als NATO-Symbole am Startort. Flights am selben Platz teilen sich ein Symbol; Namen erscheinen ab näherem Zoom.</li></ul><p><strong>Flugplätze und Bodenstationen</strong> gibt es für alle DCS-Karten (Caucasus, Syria, Persian Gulf, Sinai, Iraq, Afghanistan, Kola, Germany CW, Nevada, Normandy, Marianas, Falklands). Ein Klick zeigt Frequenzen, TACAN, ILS und Bahnen.</p><h2 id="symbole-und-farben" tabindex="-1">Symbole und Farben <a class="header-anchor" href="#symbole-und-farben" aria-label="Permalink to &quot;Symbole und Farben&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Auf der Karte</th><th>Bedeutung</th></tr></thead><tbody><tr><td>Blaue Linie mit Nummern</td><td>Route des gewählten Flights, Nummern = Steerpoints</td></tr><tr><td>Rote Raute, Ring</td><td>Freigegebene Bedrohung mit Reichweite</td></tr><tr><td>Graue Raute</td><td>Bedrohung, die (noch) verborgen ist – nur der Designer sieht sie</td></tr><tr><td>Blaue Rahmen-Symbole</td><td>Eigene Luftabwehr und Kräfte (NATO-Symbole)</td></tr><tr><td>Rotes Fadenkreuz</td><td>Bullseye</td></tr><tr><td>Farbige Flächen und Linien</td><td>Zeichnungen aus dem Mission Editor und taktische Grafiken</td></tr></tbody></table><h2 id="routen-direkt-auf-der-karte-bearbeiten" tabindex="-1">Routen direkt auf der Karte bearbeiten <a class="header-anchor" href="#routen-direkt-auf-der-karte-bearbeiten" aria-label="Permalink to &quot;Routen direkt auf der Karte bearbeiten&quot;">​</a></h2><p>Im Bereich <strong>Flights</strong> kannst du die Route des gewählten Flights auf der Karte ändern:</p><ul><li><strong>Punkt ziehen</strong> verschiebt ihn.</li><li><strong>„+“ zwischen zwei Punkten</strong> fügt einen neuen ein.</li><li><strong>Rechtsklick</strong> auf einen Punkt entfernt ihn.</li></ul><p>Hat der Flight eine Cartridge, bearbeitest du deren Steerpoints im <a href="/bereiche/dtc">DTC-Editor</a> – dort setzen Klicks auf die Karte neue Punkte.</p><h2 id="koordinaten-und-zeit" tabindex="-1">Koordinaten und Zeit <a class="header-anchor" href="#koordinaten-und-zeit" aria-label="Permalink to &quot;Koordinaten und Zeit&quot;">​</a></h2><p>Oben rechts wählst du das <strong>Koordinatenformat</strong> (DDM, DMS, DD, MGRS) und den <strong>Zeitbezug</strong> (L = Ortszeit der Karte, Z = Zulu). Das gilt in der ganzen App, auch auf Kneeboards.</p><p>Die Zeitzone jeder Karte ist voreingestellt. Stimmt sie nicht, klick auf <strong>UTC±</strong> und trag die Abweichung ein – sie wird mit der Mission gespeichert.</p><h2 id="rechtsklick-hier" tabindex="-1">Rechtsklick: „Hier …“ <a class="header-anchor" href="#rechtsklick-hier" aria-label="Permalink to &quot;Rechtsklick: „Hier …“ {#rechtsklick-hier}&quot;">​</a></h2><p>Ein Rechtsklick auf die freie Karte öffnet ein Menü für genau diese Stelle. Oben stehen Koordinate und Bullseye-Peilung, darunter, was du dort anlegen kannst – was zum Bereich passt, steht zuerst:</p><table tabindex="0"><thead><tr><th>Eintrag</th><th>Was passiert</th></tr></thead><tbody><tr><td><strong>Wegpunkt für … anhängen</strong></td><td>Hängt der Route des gewählten Flights hier einen Wegpunkt an (Bereich Flights, Designer, Route aus dem Mission Editor).</td></tr><tr><td><strong>Planungspunkt</strong></td><td>RV, Marshal, Holding, CP, IP, Push, Fence, TGT oder Fix an dieser Stelle; öffnet den Punkt in der <a href="/bereiche/planung">Planung</a>. Nur Designer.</td></tr><tr><td><strong>Grafik oder Form ab hier</strong></td><td>Klappt die Palette auf: Orbits, Linien, Gebiete, Punkte und freie Formen. Der erste Punkt sitzt schon hier, die weiteren klickst du wie gewohnt. Nur Designer.</td></tr><tr><td><strong>Bedrohung hier eintragen</strong></td><td>Eigener Threat des gewählten Systems; öffnet ihn im <a href="/bereiche/intel">Intel</a>. Als Flight nur mit der Freigabe „Eigene Threats“, und nur für den eigenen Flight.</td></tr><tr><td><strong>Messen ab hier</strong></td><td>Startet das Messen mit dem ersten Punkt an dieser Stelle.</td></tr><tr><td><strong>Koordinate kopieren</strong></td><td>Im gewählten Format in die Zwischenablage.</td></tr></tbody></table><p>Ist ein Werkzeug aktiv (Zeichnen, Messen …), kopiert der Rechtsklick wie bisher direkt die Koordinate.</p>',21)])])}const c=t(a,[["render",d]]);export{b as __pageData,c as default};
